import gzip, csv, sys
from collections import defaultdict

peaks=[]
with gzip.open('/inputs/ENCFF401MQL.bed.gz','rt') as fh:
    for i,l in enumerate(fh):
        f=l.rstrip('\n').split('\t')
        peaks.append([f[0],int(f[1]),int(f[2]),f[6],i])
motifs=[]
with gzip.open('/inputs/MA0139.1.tsv.gz','rt') as fh:
    for j,l in enumerate(fh):
        f=l.rstrip('\n').split('\t')
        motifs.append((f[0],int(f[1]),int(f[2]),f[5],f[6],j))
bl=[]
with gzip.open('/inputs/ENCFF356LFX.bed.gz','rt') as fh:
    for l in fh:
        f=l.rstrip('\n').split('\t'); bl.append((f[0],int(f[1]),int(f[2])))

order=[]; info={}
for ch,s,e,fc,i in peaks:
    if (ch,s,e) not in info: info[(ch,s,e)]=fc; order.append((ch,s,e))
mby=defaultdict(list)
for m in motifs: mby[m[0]].append(m)

mode = sys.argv[1]  # 'earliest' or 'latest'
assigned={}
for (ch,s,e) in order:
    best=None
    for m in mby.get(ch,()):
        ms,me,mp,mst,mj = m[1],m[2],m[3],m[4],m[5]
        if ms < e and s < me:
            pv = int(mp)
            if best is None: best=[pv,mj,m]
            else:
                if mode=='earliest':
                    if pv > best[0] or (pv==best[0] and mj < best[1]): best=[pv,mj,m]
                else:
                    if pv > best[0] or (pv==best[0] and mj > best[1]): best=[pv,mj,m]
    if best is not None: assigned[(ch,s,e)]=best[2]

cuts=defaultdict(list)
for ch,s,e in bl: cuts[ch].append((s-1000,e+1000))
merged={}
for ch,ivs in cuts.items():
    ivs.sort(); out=[]
    for s,e in ivs:
        if out and s<=out[-1][1]: out[-1][1]=max(out[-1][1],e)
        else: out.append([s,e])
    merged[ch]=out
def trim(s,e,cs):
    pieces=[]; cur=s
    for a,b in cs:
        if b<=cur: continue
        if a<=cur: cur=b; continue
        if a>=e: break
        pieces.append((cur,a)); cur=b
    if cur<e: pieces.append((cur,e))
    return [p for p in pieces if p[0]<p[1]]

rows=[]
split=0; removed=0; trimmed=0
for key in order:
    ch,s,e=key; fc=info[key]; m=assigned.get(key)
    pieces=trim(s,e,merged.get(ch,[]))
    if not pieces: removed+=1; continue
    if len(pieces)>1: split+=1
    if pieces[0][0]!=s or pieces[-1][1]!=e: trimmed+=1
    for ps,pe in pieces:
        if m is None: rows.append([ch,ps,pe,fc,'','','','',''])
        else: rows.append([ch,ps,pe,fc,m[0],m[1],m[2],m[3],m[4]])
print(f"[{mode}] rows={len(rows)} splits={split} fully_removed={removed} trimmed_peaks={trimmed}")
with open(f'out_{mode}.csv','w',newline='') as fh:
    w=csv.writer(fh, lineterminator='\n')
    w.writerow(['chrom','start','end','fc','chrom_2','start_2','end_2','pval_2','strand_2'])
    for r in rows:
        out=[r[0], r[1], r[2], str(float(r[3])) if r[3]!='' else '']
        if r[4]=='': out += ['','','','']
        else: out += [r[4], r[5], r[6], str(float(r[7])), r[8]]
        w.writerow(out)
